from __future__ import absolute_import
import shutil
import tempfile
import time
import logging
from easyprocess import EasyProcess
from pyvirtualdisplay import Display
from collections import OrderedDict
from taf.ul.oam.selenium_core.download_tools import Downloader
from taf.ul.oam.selenium_core.webdrivers import CustomWebdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support import expected_conditions as EC
from .pages import LoginPage, SoftwareManagerPage, CommonPage
from .exceptions import PageDoesNotExist


class netact(object):
    """
    Keywords for NetAct tool


    ..note:: netact lib requires display drivers to be installed
    at the machine on which tests are run. If one needs run tests without
    display options should install xvfb tool at the machine.
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2

    _HOME_PAGE = "Start Page"
    _CONFIGURATION_SOFTWARE_MANAGER_PAGE = "Software Manager"
    _CONFIGURATION_SOFTWARE_MANAGER_XPATH = "//a[contains(@href,'swm-web')]"

    def __init__(self):
        self.page = None
        self.__driver = None
        self._download_dir = None
        self._tmp_download_dir = False
        self._url = None
        self._username = None
        self._password = None
        self._display = None
        self.downloader = Downloader()
        self.page_handle = OrderedDict()
        self.page_instance = OrderedDict()

    @property
    def download_dir(self):
        """ Get download directory path.
        If path was not provided, function returns path to temporary directory,
        which will be removed during logout. """
        return self.get_download_dir()

    def get_download_dir(self):
        """ Function for compatibility with robot framework.  See download_dir property. """
        if self._download_dir is None:
            self._download_dir = tempfile.mkdtemp(suffix="ta-selenium-metact")
            self._tmp_download_dir = True
        return self._download_dir

    @download_dir.setter
    def download_dir(self, download_dir):
        """ Set download directory path.
        Note that this function can be called only before driver initialization.

        :param download_dir: path to download dir
        """
        self.set_download_dir(download_dir)

    def set_download_dir(self, download_dir):
        """ Function for compatibility with robot framework. See download_dir property. """
        if self.__driver is None:
            self._download_dir = download_dir
        else:
            raise AttributeError("Download dir must be set")

    @property
    def _driver(self):
        if self.__driver is None:
            self.__driver = CustomWebdriver(self.download_dir)
        return self.__driver

    def enable_virtual_display(self, width=1920, height=1280):
        """
        This keyword is used to enable virtual display, the browser will not be shown up.
        Please make sure to call this method before all manipulates(login included) if you
        don't want browser popped up.
        Please make sure "xvfb" service installed on the environment.
        :param width: int, width of browser
        :param height: int, height of browser
        """
        self._display = Display(visible=0, size=(width, height))
        self._display.start()

    def disable_virtual_display(self):
        """
        This keyword is used to disable virtual display.
        Please make sure to call this method at the end of test if you've call "enable_virtual_display"
        """
        self._display.stop()

    def login(self, url, username, password):
        """
        Login into NetAct

        :param url: url to netact management system
        :param username: username
        :param password: password
        """
        self._driver.get(url)
        self._url = url
        self._username = username
        self._password = password
        self.page = LoginPage(self._driver)
        self.wait_for_visibility(r'//input[@name="login:username"]')
        self.page = self.page.login(username, password)
        self.page_handle[self._HOME_PAGE] = self._driver.current_window_handle
        self.page_instance[self._HOME_PAGE] = self.page

    def logout(self):
        """
        Closes browser and remove contents of download dir if download dir path was not provided.
        """
        if self._tmp_download_dir:
            shutil.rmtree(self.download_dir)
            self._tmp_download_dir = False
            self._download_dir = None
        try:
            for page in self.page_handle.keys():
                if page != self._HOME_PAGE:
                    self.close_page(page)
            self.page = self.page_instance.get(self._HOME_PAGE)
            self.page.logout()
        finally:
            self._driver.close()
            self.__driver = None
            self.page_handle.clear()
            self.page_instance.clear()

    def login_for_lab_access(self, url, username, password):
        """
            Login into lab access page

            :param url: url to lab access page
            :param username: username
            :param password: password
            """
        self._lab_access_driver = CustomWebdriver(self.download_dir)
        self._lab_access_driver.get(url)
        self._lab_access_driver.find_element_by_id("username").send_keys(username)
        self._lab_access_driver.find_element_by_id("password").send_keys(password)
        self._lab_access_driver.find_element_by_id("btnSubmit_6").click()

    def logout_lab_access(self):
        """
        Closes browser and remove contents of download dir if download dir path was not provided.
        """
        self._lab_access_driver.close()

    def open_configuration_software_manager(self):
        """
        Open NetAct configuration software manager page.
        """
        logging.info("Current used Firefox version is: %s", EasyProcess(["firefox", "--version"]).call().stdout)
        self.page.click_configuration()
        self._click_page_by_xpath(self._CONFIGURATION_SOFTWARE_MANAGER_XPATH,
                                  self._CONFIGURATION_SOFTWARE_MANAGER_PAGE)
        self.page_instance[self._CONFIGURATION_SOFTWARE_MANAGER_PAGE] = SoftwareManagerPage(self._driver)
        self.switch_to_page(self._CONFIGURATION_SOFTWARE_MANAGER_PAGE)

    def open_sub_page(self, category_xpath, page_xpath, page_name):
        """
        open sub page,for example ,NeIntegration(page) under Administration(category)
        :param category_xpath: xpath of category
        :param page_xpath: xpath of page
        :param page_name: name of your page
        """
        self.page.click_home()
        self.wait_for_visibility(category_xpath)
        self.page.click_element(category_xpath)
        self.wait_for_visibility(page_xpath)
        self._click_page_by_xpath(page_xpath, page_name)
        self.page_instance[page_name] = CommonPage(self._driver)
        self.switch_to_page(page_name)

    def open_sub_page_by_xpath_list(self, sub_page_xpath_list, page_name, timeout=5):
        """
        open sub page, for example, Summary report page under Software Asset Monitoring page
        :param sub_page_xpath_list: list, xpath list for open sub page, each element which is specified
                                    by xpath will be clicked
        :param page_name: str, alias name of the sub page which will be opened
        :param timeout: int, timeout value, default is 5s
        """
        for xpath in sub_page_xpath_list[:-1]:
            self.wait_for_visibility(xpath)
            self.page.click_element(xpath)

        self.wait_for_visibility(sub_page_xpath_list[-1])
        self._click_page_by_xpath(sub_page_xpath_list[-1], page_name, timeout)
        self.page_instance[page_name] = CommonPage(self._driver)
        self.switch_to_page(page_name)

    def get_configuration_cm_operations_manager(self, download_timeout=20):
        """
        Open NetAct configuration cm operations manager page.
        """
        start_downloading_time = time.time()
        self.page.click_configuration_cm_operations_manager()
        return self.downloader.download(download_dir=self.download_dir,
                                        start_downloading_time=start_downloading_time,
                                        download_timeout=download_timeout)

    def _click_page_by_xpath(self, page_xpath, page_name, timeout=5):
        """
        Switch to window by given page handle.

        :param page_xpath: element xpath to locate page
        :param page_name: dict key to locate page handle
        """
        self.page.click_element(page_xpath)
        self.wait_for_new_window_open(timeout)
        for handle in self._driver.window_handles:
            if handle not in self.page_handle.values():
                self.page_handle[page_name] = handle

    def switch_to_page(self, page_name):
        """
        Switch to window by given page handle.

        :param page_name: dict key to locate page handle
        """
        if page_name in self.page_handle.keys():
            self._driver.switch_to.window(self.page_handle.get(page_name))
            self.page = self.page_instance.get(page_name)
        else:
            raise PageDoesNotExist("Page does not exist, handle should be in {}.\n".format(self.page_handle.keys()))

    def close_page(self, page_name):
        """
        Close window by given page handle, switch to home page.

        :param page_name: dict key to locate page handle
        """
        if page_name != self._HOME_PAGE:
            self.switch_to_page(page_name)
            self._driver.close()
            self._driver.switch_to.window(self.page_handle.get(self._HOME_PAGE))
            self.page_handle.pop(page_name)
            self.page_instance.pop(page_name)
        else:
            raise Exception('Please use logout() to close NetAct Start Page.')

    def switch_to_network_status(self):
        """
        Switch to tab Network Status.
        """
        self.page.click_network_status()

    def switch_to_network_operations(self):
        """
        Switch to tab Network Operations.
        """
        self.page.click_network_operations()

    def switch_to_schedules(self):
        """
        Switch to tab Schedules.
        """
        self.page.click_schedules()

    def switch_to_software_archive(self):
        """
        Switch to tab Software Archive.
        """
        self.page.click_software_archive()

    def switch_to_backup_archive(self):
        """
        Switch to tab Backup Archive.
        """
        self.page.click_backup_archive()

    def switch_to_preferences(self):
        """
        Switch to tab Preferences.
        """
        self.page.click_preferences()

    def select_checkbox(self, checkbox_xpath):
        """
        select checkbox
        :param checkbox_xpath: element xpath
        """
        self.page.select_element(checkbox_xpath)

    def unselect_checkbox(self, checkbox_xpath):
        """
        unselect checkbox
        :param checkbox_xpath: element xpath
        """
        self.page.select_element(checkbox_xpath, False)

    def select_radio(self, radio_xpath):
        """
        select radio
        :param radio_xpath: element xpath
        """
        self.page.click_element(radio_xpath)

    def write_value(self, input_xpath, value):
        """
        write value to input element
        :param input_xpath: input element xpath
        """
        self.page.write_value(input_xpath, value)

    def write_value_and_enter(self, input_xpath, value):
        """
        write value to input element and key 'enter'
        :param input_xpath: input element xpath
        """
        self.page.write_value_and_enter(input_xpath, value)

    def click_button(self, button_xpath):
        """
        click button
        :param button_xpath: element xpath
        """
        self.page.click_element(button_xpath)

    def expand_tree(self, tree_elem_xpath):
        """
        expand tree
        :param tree_elem_xpath: tree element xpath
        """
        self.page.expand_tree_by_elem_xpath(tree_elem_xpath)

    def wait_for_visibility(self, elem_xpath, timeout=None):
        """
        wait for element visible
        :param elem_xpath: element xpath
        :param timeout: int timeout value, default is 60s
        """
        if timeout is not None:
            self.page.wait_for_visibility((By.XPATH, elem_xpath), int(timeout))
        else:
            self.page.wait_for_visibility((By.XPATH, elem_xpath))

    def wait_for_enable(self, elem_xpath, timeout=None):
        """
        wait for element enable
        :param elem_xpath: element xpath
        :param timeout: int timeout value, default is 60s
        """
        if timeout is not None:
            self.page.wait_for_enable((By.XPATH, elem_xpath), int(timeout))
        else:
            self.page.wait_for_enable((By.XPATH, elem_xpath))

    def wait_for_new_window_open(self, timeout=5):
        """
        wait for new window to open
        :param timeout: int timeout value, default is 5s
        """
        self.page._until(EC.new_window_is_opened(self.page_handle), timeout)

    def get_elem_text(self, elem_xpath):
        """
        get element text value
        :param elem_xpath: element xpath
        """
        return self.page.get_elem_text(elem_xpath)

    def get_element_attribute(self, elem_xpath, attr_name):
        """
        get element attribute value
        :param elem_xpath: element xpath
        :param attr_name: attribute name
        :return attribute value
        """
        return self.page.get_element_attribute(elem_xpath, attr_name)

    def execute_script(self, script_cmd, elem_xpath=None):
        """
        execute script_cmd, if script_cmd contains argument, pass elem_xpath of this argument
        :param script_cmd: script command want to use in driver
        :param elem_xpath: element xpath
        """
        if elem_xpath:
            elem = self._driver.find_element_by_xpath(elem_xpath)
            return self._driver.execute_script(script_cmd, elem)
        else:
            return self._driver.execute_script(script_cmd)

    def move_to_element(self, elem_xpath):
        """
        move mouse to element by xpath.
        if element is dynamic generated and can not be selected directly by click button,
        can firstly move to element, then try click button.
        :param elem_xpath: element xpath
        """
        self.page.move_to_element(elem_xpath)

    def scroll_element_to_view(self, elem_xpath):
        """ Scroll to element to make sure element visiable
        :param elem_xpath: xpath of element
        """
        self.page.scroll_element_to_view(elem_xpath)
